head.script:
scwin.trigger1_onclick = function(e) {
    var temp = [{
        "col1": "aa",
        "col2": "bb",
        "col3": "a2"
    }];
    dataList1.setJSON(temp);
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 checkcombobox를 선택하여 값(a3)을 선택한다.
    //1. After running the sample file, select checkcombobox and select the value (a3).
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('checkcombobox1_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('checkcombobox1_itemTable_2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('checkcombobox1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. checkcombobox의 값(a3)이 선택되어진다.
    //1. The value of checkcombobox (a3) is selected.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('checkcombobox1_itemTable_2_checkbox').checked", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('checkcombobox1_label').innerText == 'a3'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 'gridViewdataList1.setJSON'버튼을 클릭한다.
    //2. Click the 'gridViewdataList1.setJSON' button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. checkcombobox의 값(a3)이 계속 유지된다. (이전에는 초기화되어짐)
    //2. The value of checkcombobox (a3) is kept. (Previously initialized)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('checkcombobox1_label').innerText == 'a3'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.jsonData = [{
        "label": "a1",
        "value": "a1",
        "a": "a"
    }, {
        "label": "a2",
        "value": "a2",
        "a": "a"
    }, {
        "label": "b1",
        "value": "b1",
        "a": "b"
    }, {
        "label": "a3",
        "value": "a3",
        "a": "a"
    }];
    dataList2.setJSON(jsonData);
    window.temp = [{
        "col1": "1",
        "col2": "2",
        "col3": "a1"
    }];
    dataList1.setJSON(temp);
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 31-Jan-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
